INSERT INTO plant_dictionary (label, name_kr, description) VALUES
                                                               ('PhilodendronGloriosum', '필로덴드론 글로리오섬', '크고 심장 모양의 잎에 벨벳 질감이 특징인 열대 식물입니다.'),
                                                               ('PileaPeperomioides', '필리아 페페', '동전 모양의 동그란 잎이 특징이며 다산과 행운을 상징합니다.'),
                                                               ('MonsteraVariegata', '몬스테라 바리에가타', '잎에 흰색 무늬가 섞인 희귀 식물로 일반종보다 빛이 더 필요합니다.'),
                                                               ('CalatheaStromantheTriostar', '칼라데아 스트로만데 멀티컬러', '잎 뒷면의 붉은색과 앞면의 분홍 무늬가 매우 화려한 식물입니다.'),
                                                               ('AlocasiaFrydek', '알로카시아 프라이덱', '짙은 녹색 잎에 은색 잎맥이 강렬한 대조를 이루는 미적 가치가 높은 식물입니다.'),
                                                               ('CalatheaFusionWhite', '칼라데아 퓨전화이트', '그림을 그린 듯한 흰 무늬가 아름답지만 습도에 매우 민감합니다.'),
                                                               ('Monstera', '몬스테라', '잎에 구멍이 뚫리는 독특한 모습으로 실내 인테리어 식물의 대명사입니다.'),
                                                               ('Ivy', '아이비', '생명력이 매우 강한 덩굴 식물로 공기 정화 능력이 탁월합니다.'),
                                                               ('AlocasiaAmazonica', '거북 알로카시아', '화살촉 모양의 잎과 굵은 잎맥이 특징인 열대 관엽식물입니다.'),
                                                               ('PeaceLily', '스파티필름', '하얀 꽃처럼 보이는 불염포가 매력적이며 수경 재배로도 잘 자랍니다.'),
                                                               ('CalatheaFreddie', '칼라데아 프레디', '은빛 잎에 녹색 줄무늬가 규칙적으로 배열된 모던한 느낌의 식물입니다.'),
                                                               ('Pothos', '스킨답서스', '초보자가 키우기 가장 쉬운 식물로 어두운 곳에서도 잘 버티는 강인함을 가졌습니다.'),
                                                               ('CalatheaOrnata', '칼라데아 오나타', '짙은 녹색 잎에 분홍색 선이 그어진 듯한 고급스러운 무늬를 가졌습니다.'),
                                                               ('AglaonemaRedZircon', '아글라오네마 지리홍', '잎 전체가 붉은빛으로 물들어 공간에 생기를 주는 식물입니다.'),
                                                               ('ChainOfHearts', '러브체인', '하트 모양의 작은 잎들이 줄줄이 늘어지는 형태의 다육 식물입니다.'),
                                                               ('BostonFern', '보스턴 고사리', '풍성하고 섬세한 잎으로 천연 가습기 역할을 하는 고사리류 식물입니다.'),
                                                               ('CtenantheLubbersiana', '칼라데아 크테난테 루베르시아나', '노란색 불규칙한 무늬가 시원한 느낌을 주는 키 큰 관엽식물입니다.'),
                                                               ('CalatheaAmagris', '칼라데아 아마그리스', '작고 동그란 은색 잎이 귀여우며 공간 차지를 적게 하는 칼라테아입니다.'),
                                                               ('PaintedBonsai', '수채화 고무나무', '정교하게 수형을 잡은 예술적 형태의 관상용 분재 식물입니다.'),
                                                               ('MonsteraAdansonii', '몬스테라 아단소니', '일반 몬스테라보다 잎이 작고 구멍이 촘촘하게 뚫린 매력적인 종입니다.'),
                                                               ('AglaonemaSnowdrop', '아글라오네마 스노우화이트', '흰색과 초록색이 섞여 청량감을 주며 빛이 적은 실내에서도 잘 자랍니다.'),
                                                               ('BanyanTree', '뱅갈 고무나무', '밝은 연두색 잎과 흰 줄기가 특징이며 미세먼지 제거 효과가 큽니다.'),
                                                               ('FicusElastica', '인도 고무나무', '광택이 나는 두꺼운 잎이 특징이며 생명력이 매우 강합니다.'),
                                                               ('Adiantum', '아디안텀', '은행잎을 닮은 아주 얇고 섬세한 잎을 가진 습기를 사랑하는 식물입니다.') ON CONFLICT DO NOTHING;
INSERT INTO disease_dictionary (label, name_kr, symptoms, solutions, prevention, danger_level) VALUES
                                                                                                   ('browning', '갈색 변색 (Browning)', '잎 끝이나 가장자리가 갈색으로 마르거나 타들어 갑니다.', '공기 중 습도를 높이고 직사광선을 피해주세요.', '규칙적인 분무와 적절한 물주기 주기를 유지하세요.', 'MEDIUM'),
                                                                                                   ('black spot', '검은 점 (Black Spot)', '잎 표면에 검은색 또는 암갈색 반점이 나타납니다.', '병든 잎을 즉시 제거하고 살균제를 살포하세요.', '통풍을 원활하게 하고 잎에 직접 물이 닿지 않게 하세요.', 'HIGH'),
                                                                                                   ('lower leaf', '하엽 탈락 (Lower Leaf Drop)', '식물 아래쪽 잎이 노랗게 변하며 힘없이 떨어집니다.', '자연스러운 노화일 수 있으나 과습 여부를 확인하세요.', '주기적인 영양 공급과 환기에 신경 써주세요.', 'LOW'),
                                                                                                   ('dropping', '잎 처짐 (Dropping)', '식물 전체가 축 처지고 잎에 힘이 없습니다.', '즉시 물을 흠뻑 주고 통풍이 잘 되는 곳에 두세요.', '흙의 건조 상태를 수시로 확인하고 물주기를 놓치지 마세요.', 'MEDIUM'),
                                                                                                   ('curling', '잎 말림 (Curling)', '잎이 안쪽이나 바깥쪽으로 돌돌 말리는 현상입니다.', '해충(응애 등) 유무를 확인하거나 빛의 세기를 조절하세요.', '적절한 광량 유지와 정기적인 잎 닦기를 권장합니다.', 'MEDIUM')ON CONFLICT DO NOTHING;